-- ============ Core · tenancy, identity, access ============
CREATE TABLE `schools` (
  `id` TEXT NOT NULL,
  `code` TEXT NOT NULL,
  `name` TEXT NOT NULL,
  `name_bn` TEXT,
  `institution_type` TEXT NOT NULL DEFAULT 'school',
  `board` TEXT,
  `eiin` TEXT,
  `mpo_code` TEXT,
  `address` TEXT,
  `phone` TEXT,
  `email` TEXT,
  `website` TEXT,
  `logo_file_id` TEXT,
  `timezone` TEXT NOT NULL DEFAULT 'Asia/Dhaka',
  `currency` TEXT NOT NULL DEFAULT 'BDT',
  `locale` TEXT NOT NULL DEFAULT 'bn',
  `plan_id` TEXT REFERENCES `saas_plans`(`id`) ON DELETE SET NULL,
  `status` TEXT NOT NULL DEFAULT 'trial',
  `trial_ends_at` TEXT,
  `settings` TEXT,
  `theme` TEXT,
  `custom_domain` TEXT,
  `onboarded_at` TEXT,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `deleted_at` TEXT,
  PRIMARY KEY (`id`),
  UNIQUE (`code`),
  UNIQUE (`custom_domain`),
  CHECK (`institution_type` IN ('school', 'college', 'school_college', 'madrasa', 'kindergarten', 'coaching', 'university')),
  CHECK (`status` IN ('trial', 'active', 'suspended', 'closed'))
);
CREATE INDEX `ix_schools_plan_id` ON `schools` (`plan_id`);

