-- ============ Academic structure ============
CREATE TABLE `academic_years` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `start_date` TEXT NOT NULL,
  `end_date` TEXT NOT NULL,
  `is_current` INTEGER NOT NULL DEFAULT 0,
  `status` TEXT NOT NULL DEFAULT 'planned',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `name`),
  CHECK (`status` IN ('planned', 'active', 'closed'))
);
CREATE INDEX `ix_academic_years_school_id` ON `academic_years` (`school_id`);

CREATE TABLE `terms` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `academic_year_id` TEXT NOT NULL REFERENCES `academic_years`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `sequence` INTEGER NOT NULL,
  `start_date` TEXT NOT NULL,
  `end_date` TEXT NOT NULL,
  `kind` TEXT NOT NULL DEFAULT 'term',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`academic_year_id`, `sequence`),
  CHECK (`kind` IN ('term', 'semester', 'trimester'))
);
CREATE INDEX `ix_terms_school_id` ON `terms` (`school_id`);
CREATE INDEX `ix_terms_academic_year_id` ON `terms` (`academic_year_id`);

CREATE TABLE `shifts` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `start_time` TEXT NOT NULL,
  `end_time` TEXT NOT NULL,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `name`)
);
CREATE INDEX `ix_shifts_school_id` ON `shifts` (`school_id`);

CREATE TABLE `programs` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `code` TEXT NOT NULL,
  `level` TEXT NOT NULL,
  `duration_terms` INTEGER,
  `total_credits` NUMERIC,
  `department_id` TEXT,
  `status` TEXT NOT NULL DEFAULT 'active',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `code`),
  CHECK (`level` IN ('secondary', 'higher_secondary', 'bachelor', 'master', 'diploma', 'coaching')),
  CHECK (`status` IN ('active', 'inactive'))
);
CREATE INDEX `ix_programs_school_id` ON `programs` (`school_id`);

CREATE TABLE `classes` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `name_bn` TEXT,
  `numeric_level` INTEGER NOT NULL,
  `stream` TEXT,
  `program_id` TEXT REFERENCES `programs`(`id`) ON DELETE SET NULL,
  `status` TEXT NOT NULL DEFAULT 'active',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `name`),
  CHECK (`status` IN ('active', 'inactive'))
);
CREATE INDEX `ix_classes_school_id` ON `classes` (`school_id`);
CREATE INDEX `ix_classes_program_id` ON `classes` (`program_id`);

CREATE TABLE `rooms` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `campus_id` TEXT NOT NULL REFERENCES `campuses`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `building` TEXT,
  `floor` TEXT,
  `capacity` INTEGER,
  `room_type` TEXT NOT NULL DEFAULT 'classroom',
  `amenities` TEXT,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`campus_id`, `name`),
  CHECK (`room_type` IN ('classroom', 'lab', 'hall', 'library', 'office', 'playground', 'other'))
);
CREATE INDEX `ix_rooms_school_id` ON `rooms` (`school_id`);
CREATE INDEX `ix_rooms_campus_id` ON `rooms` (`campus_id`);

CREATE TABLE `sections` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `academic_year_id` TEXT NOT NULL REFERENCES `academic_years`(`id`) ON DELETE CASCADE,
  `class_id` TEXT NOT NULL REFERENCES `classes`(`id`) ON DELETE RESTRICT,
  `campus_id` TEXT REFERENCES `campuses`(`id`) ON DELETE SET NULL,
  `shift_id` TEXT REFERENCES `shifts`(`id`) ON DELETE SET NULL,
  `name` TEXT NOT NULL,
  `capacity` INTEGER NOT NULL DEFAULT 40,
  `room_id` TEXT REFERENCES `rooms`(`id`) ON DELETE SET NULL,
  `class_teacher_id` TEXT,
  `gender_policy` TEXT NOT NULL DEFAULT 'mixed',
  `medium` TEXT NOT NULL DEFAULT 'bangla',
  `status` TEXT NOT NULL DEFAULT 'active',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`academic_year_id`, `class_id`, `name`),
  CHECK (`gender_policy` IN ('mixed', 'boys', 'girls')),
  CHECK (`medium` IN ('bangla', 'english', 'arabic')),
  CHECK (`status` IN ('active', 'inactive'))
);
CREATE INDEX `ix_sections_school_id` ON `sections` (`school_id`);
CREATE INDEX `ix_sections_academic_year_id` ON `sections` (`academic_year_id`);
CREATE INDEX `ix_sections_class_id` ON `sections` (`class_id`);
CREATE INDEX `ix_sections_campus_id` ON `sections` (`campus_id`);
CREATE INDEX `ix_sections_shift_id` ON `sections` (`shift_id`);
CREATE INDEX `ix_sections_room_id` ON `sections` (`room_id`);

CREATE TABLE `subjects` (
  `id` TEXT NOT NULL,
