CREATE TABLE `staff` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `user_id` TEXT REFERENCES `users`(`id`) ON DELETE SET NULL,
  `employee_no` TEXT NOT NULL,
  `first_name` TEXT NOT NULL,
  `last_name` TEXT,
  `name_bn` TEXT,
  `gender` TEXT,
  `date_of_birth` TEXT,
  `phone` TEXT,
  `email` TEXT,
  `nid_no` TEXT,
  `photo_file_id` TEXT REFERENCES `files`(`id`) ON DELETE SET NULL,
  `campus_id` TEXT REFERENCES `campuses`(`id`) ON DELETE SET NULL,
  `department_id` TEXT REFERENCES `departments`(`id`) ON DELETE SET NULL,
  `designation_id` TEXT REFERENCES `designations`(`id`) ON DELETE SET NULL,
  `reports_to_id` TEXT REFERENCES `staff`(`id`) ON DELETE SET NULL,
  `staff_category` TEXT NOT NULL DEFAULT 'teaching',
  `employment_type` TEXT NOT NULL DEFAULT 'permanent',
  `mpo_index_no` TEXT,
  `join_date` TEXT NOT NULL,
  `probation_end` TEXT,
  `leave_date` TEXT,
  `status` TEXT NOT NULL DEFAULT 'active',
  `address` TEXT,
  `emergency_contact` TEXT,
  `bank_details` TEXT,
  `biometric_id` TEXT,
  `rfid_tag` TEXT,
  `meta` TEXT,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `deleted_at` TEXT,
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `employee_no`),
  UNIQUE (`user_id`),
  CHECK (`gender` IN ('male', 'female', 'other')),
  CHECK (`staff_category` IN ('teaching', 'non_teaching', 'admin', 'support')),
  CHECK (`employment_type` IN ('permanent', 'contract', 'part_time', 'intern', 'volunteer', 'mpo')),
  CHECK (`status` IN ('active', 'probation', 'on_leave', 'resigned', 'terminated', 'retired'))
);
CREATE INDEX `ix_staff_school_id` ON `staff` (`school_id`);
CREATE INDEX `ix_staff_photo_file_id` ON `staff` (`photo_file_id`);
