  `grading_scale_id` TEXT NOT NULL REFERENCES `grading_scales`(`id`) ON DELETE RESTRICT,
  `name` TEXT NOT NULL,
  `start_date` TEXT NOT NULL,
  `end_date` TEXT NOT NULL,
  `marks_entry_deadline` TEXT,
  `publish_at` TEXT,
  `status` TEXT NOT NULL DEFAULT 'draft',
  `require_fee_clearance` INTEGER NOT NULL DEFAULT 0,
  `min_attendance_pct` NUMERIC,
  `rank_scope` TEXT NOT NULL DEFAULT 'section',
