  `remark` TEXT NOT NULL,
  `polarity` TEXT NOT NULL DEFAULT 'neutral',
  `visible_to_guardian` INTEGER NOT NULL DEFAULT 1,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  CHECK (`polarity` IN ('positive', 'neutral', 'concern'))
);
CREATE INDEX `ix_student_remarks_school_id` ON `student_remarks` (`school_id`);
CREATE INDEX `ix_student_remarks_student_id` ON `student_remarks` (`student_id`);
CREATE INDEX `ix_student_remarks_teacher_id` ON `student_remarks` (`teacher_id`);


-- ============ Co-curricular · clubs, sports, achievements, portfolio ============
CREATE TABLE `clubs` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `category` TEXT NOT NULL DEFAULT 'other',
  `advisor_id` TEXT REFERENCES `staff`(`id`) ON DELETE SET NULL,
  `description` TEXT,
  `meeting_schedule` TEXT,
  `status` TEXT NOT NULL DEFAULT 'active',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  CHECK (`category` IN ('academic', 'sports', 'arts', 'social', 'tech', 'religious', 'other')),
  CHECK (`status` IN ('active', 'inactive'))
);
CREATE INDEX `ix_clubs_school_id` ON `clubs` (`school_id`);
CREATE INDEX `ix_clubs_advisor_id` ON `clubs` (`advisor_id`);

CREATE TABLE `club_memberships` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `club_id` TEXT NOT NULL REFERENCES `clubs`(`id`) ON DELETE CASCADE,
  `student_id` TEXT NOT NULL REFERENCES `students`(`id`) ON DELETE CASCADE,
  `role` TEXT NOT NULL DEFAULT 'member',
  `joined_on` TEXT NOT NULL,
  `left_on` TEXT,
  PRIMARY KEY (`id`),
  UNIQUE (`club_id`, `student_id`),
  CHECK (`role` IN ('member', 'secretary', 'president', 'captain'))
);
CREATE INDEX `ix_club_memberships_school_id` ON `club_memberships` (`school_id`);
CREATE INDEX `ix_club_memberships_club_id` ON `club_memberships` (`club_id`);
CREATE INDEX `ix_club_memberships_student_id` ON `club_memberships` (`student_id`);

CREATE TABLE `competitions` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `kind` TEXT NOT NULL,
  `level` TEXT NOT NULL DEFAULT 'intra',
  `held_on` TEXT,
  `venue` TEXT,
  `organiser` TEXT,
  `event_id` TEXT,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  CHECK (`kind` IN ('sports', 'academic', 'cultural', 'science', 'debate', 'olympiad', 'other')),
  CHECK (`level` IN ('intra', 'inter_school', 'district', 'national', 'international'))
);
CREATE INDEX `ix_competitions_school_id` ON `competitions` (`school_id`);

CREATE TABLE `competition_results` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `competition_id` TEXT NOT NULL REFERENCES `competitions`(`id`) ON DELETE CASCADE,
  `student_id` TEXT REFERENCES `students`(`id`) ON DELETE CASCADE,
  `club_id` TEXT REFERENCES `clubs`(`id`) ON DELETE CASCADE,
  `house_id` TEXT REFERENCES `houses`(`id`) ON DELETE CASCADE,
  `position` INTEGER,
  `award` TEXT,
  `points` INTEGER NOT NULL DEFAULT 0,
  `certificate_doc_id` TEXT,
  PRIMARY KEY (`id`)
);
CREATE INDEX `ix_competition_results_school_id` ON `competition_results` (`school_id`);
CREATE INDEX `ix_competition_results_competition_id` ON `competition_results` (`competition_id`);
CREATE INDEX `ix_competition_results_student_id` ON `competition_results` (`student_id`);
CREATE INDEX `ix_competition_results_club_id` ON `competition_results` (`club_id`);
CREATE INDEX `ix_competition_results_house_id` ON `competition_results` (`house_id`);

CREATE TABLE `house_points` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `house_id` TEXT NOT NULL REFERENCES `houses`(`id`) ON DELETE CASCADE,
  `student_id` TEXT REFERENCES `students`(`id`) ON DELETE CASCADE,
  `points` INTEGER NOT NULL,
  `reason` TEXT NOT NULL,
