-- ============ Library & e-library ============
CREATE TABLE `library_categories` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `parent_id` TEXT REFERENCES `library_categories`(`id`) ON DELETE SET NULL,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `name`)
);
CREATE INDEX `ix_library_categories_school_id` ON `library_categories` (`school_id`);
CREATE INDEX `ix_library_categories_parent_id` ON `library_categories` (`parent_id`);

CREATE TABLE `library_books` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `isbn` TEXT,
  `title` TEXT NOT NULL,
  `subtitle` TEXT,
  `authors` TEXT,
  `publisher` TEXT,
  `edition` TEXT,
  `published_year` INTEGER,
  `language` TEXT NOT NULL DEFAULT 'bn',
  `category_id` TEXT REFERENCES `library_categories`(`id`) ON DELETE SET NULL,
  `subject_id` TEXT REFERENCES `subjects`(`id`) ON DELETE SET NULL,
  `class_id` TEXT REFERENCES `classes`(`id`) ON DELETE SET NULL,
  `pages` INTEGER,
  `price` NUMERIC,
  `cover_file_id` TEXT REFERENCES `files`(`id`) ON DELETE SET NULL,
  `ebook_file_id` TEXT REFERENCES `files`(`id`) ON DELETE SET NULL,
  `description` TEXT,
  `total_copies` INTEGER NOT NULL DEFAULT 0,
  `available_copies` INTEGER NOT NULL DEFAULT 0,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`)
);
CREATE INDEX `ix_library_books_school_id` ON `library_books` (`school_id`);
CREATE INDEX `ix_library_books_category_id` ON `library_books` (`category_id`);
CREATE INDEX `ix_library_books_subject_id` ON `library_books` (`subject_id`);
CREATE INDEX `ix_library_books_class_id` ON `library_books` (`class_id`);
CREATE INDEX `ix_library_books_cover_file_id` ON `library_books` (`cover_file_id`);
CREATE INDEX `ix_library_books_ebook_file_id` ON `library_books` (`ebook_file_id`);
CREATE INDEX `ix_library_books_school_id_title` ON `library_books` (`school_id`, `title`);

CREATE TABLE `library_book_copies` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `book_id` TEXT NOT NULL REFERENCES `library_books`(`id`) ON DELETE CASCADE,
  `accession_no` TEXT NOT NULL,
  `barcode` TEXT,
  `rack` TEXT,
  `shelf` TEXT,
  `condition_note` TEXT NOT NULL DEFAULT 'good',
  `status` TEXT NOT NULL DEFAULT 'available',
  `acquired_on` TEXT,
  `source` TEXT NOT NULL DEFAULT 'purchase',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `accession_no`),
  CHECK (`condition_note` IN ('new', 'good', 'fair', 'poor')),
  CHECK (`status` IN ('available', 'issued', 'reserved', 'lost', 'damaged', 'withdrawn')),
  CHECK (`source` IN ('purchase', 'donation'))
);
CREATE INDEX `ix_library_book_copies_school_id` ON `library_book_copies` (`school_id`);
CREATE INDEX `ix_library_book_copies_book_id` ON `library_book_copies` (`book_id`);

CREATE TABLE `library_members` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `member_type` TEXT NOT NULL,
  `student_id` TEXT REFERENCES `students`(`id`) ON DELETE CASCADE,
  `staff_id` TEXT REFERENCES `staff`(`id`) ON DELETE CASCADE,
  `card_no` TEXT NOT NULL,
  `max_books` INTEGER NOT NULL DEFAULT 2,
  `loan_days` INTEGER NOT NULL DEFAULT 14,
  `fine_per_day` NUMERIC NOT NULL DEFAULT 5,
  `status` TEXT NOT NULL DEFAULT 'active',
  `blocked_reason` TEXT,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `card_no`),
  CHECK (`member_type` IN ('student', 'staff', 'guardian')),
  CHECK (`status` IN ('active', 'blocked', 'inactive'))
);
CREATE INDEX `ix_library_members_school_id` ON `library_members` (`school_id`);
CREATE INDEX `ix_library_members_student_id` ON `library_members` (`student_id`);
CREATE INDEX `ix_library_members_staff_id` ON `library_members` (`staff_id`);

CREATE TABLE `library_issues` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `copy_id` TEXT NOT NULL REFERENCES `library_book_copies`(`id`) ON DELETE RESTRICT,
  `member_id` TEXT NOT NULL REFERENCES `library_members`(`id`) ON DELETE RESTRICT,
