  `fine_invoice_item_id` TEXT,
  `fine_waived_by` TEXT REFERENCES `users`(`id`) ON DELETE SET NULL,
  `reminder_stage` TEXT,
  `status` TEXT NOT NULL DEFAULT 'issued',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  CHECK (`status` IN ('issued', 'returned', 'lost', 'overdue'))
);
CREATE INDEX `ix_library_issues_school_id` ON `library_issues` (`school_id`);
CREATE INDEX `ix_library_issues_copy_id` ON `library_issues` (`copy_id`);
CREATE INDEX `ix_library_issues_member_id` ON `library_issues` (`member_id`);
CREATE INDEX `ix_library_issues_issued_by` ON `library_issues` (`issued_by`);
CREATE INDEX `ix_library_issues_returned_to` ON `library_issues` (`returned_to`);
CREATE INDEX `ix_library_issues_fine_waived_by` ON `library_issues` (`fine_waived_by`);
CREATE INDEX `ix_library_issues_school_id_due_at` ON `library_issues` (`school_id`, `due_at`);

CREATE TABLE `library_reservations` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `book_id` TEXT NOT NULL REFERENCES `library_books`(`id`) ON DELETE CASCADE,
  `member_id` TEXT NOT NULL REFERENCES `library_members`(`id`) ON DELETE CASCADE,
