  `status` TEXT NOT NULL DEFAULT 'waiting',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  CHECK (`status` IN ('waiting', 'ready', 'fulfilled', 'expired', 'cancelled'))
);
CREATE INDEX `ix_library_reservations_school_id` ON `library_reservations` (`school_id`);
CREATE INDEX `ix_library_reservations_book_id` ON `library_reservations` (`book_id`);
CREATE INDEX `ix_library_reservations_member_id` ON `library_reservations` (`member_id`);

CREATE TABLE `reading_logs` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `student_id` TEXT NOT NULL REFERENCES `students`(`id`) ON DELETE CASCADE,
