-- ============ Fees & billing ============
CREATE TABLE `fee_heads` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `code` TEXT NOT NULL,
  `head_kind` TEXT NOT NULL DEFAULT 'academic',
  `gl_account_id` TEXT,
  `is_refundable` INTEGER NOT NULL DEFAULT 0,
  `tax_pct` NUMERIC NOT NULL DEFAULT 0,
  `status` TEXT NOT NULL DEFAULT 'active',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `code`),
  CHECK (`head_kind` IN ('academic', 'transport', 'hostel', 'fine', 'misc', 'course', 'shop', 'canteen')),
  CHECK (`status` IN ('active', 'inactive'))
);
CREATE INDEX `ix_fee_heads_school_id` ON `fee_heads` (`school_id`);

CREATE TABLE `late_fine_rules` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `grace_days` INTEGER NOT NULL DEFAULT 0,
  `fine_type` TEXT NOT NULL,
  `value` NUMERIC NOT NULL,
  `max_amount` NUMERIC,
  `fine_head_id` TEXT REFERENCES `fee_heads`(`id`) ON DELETE SET NULL,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `name`),
  CHECK (`fine_type` IN ('flat', 'percent', 'per_day', 'per_week'))
);
CREATE INDEX `ix_late_fine_rules_school_id` ON `late_fine_rules` (`school_id`);
CREATE INDEX `ix_late_fine_rules_fine_head_id` ON `late_fine_rules` (`fine_head_id`);

CREATE TABLE `fee_structures` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `academic_year_id` TEXT NOT NULL REFERENCES `academic_years`(`id`) ON DELETE CASCADE,
  `class_id` TEXT NOT NULL REFERENCES `classes`(`id`) ON DELETE CASCADE,
  `campus_id` TEXT REFERENCES `campuses`(`id`) ON DELETE SET NULL,
  `shift_id` TEXT REFERENCES `shifts`(`id`) ON DELETE SET NULL,
  `program_id` TEXT REFERENCES `programs`(`id`) ON DELETE SET NULL,
  `name` TEXT NOT NULL,
  `status` TEXT NOT NULL DEFAULT 'active',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`academic_year_id`, `class_id`, `campus_id`, `shift_id`, `program_id`),
  CHECK (`status` IN ('active', 'inactive'))
);
CREATE INDEX `ix_fee_structures_school_id` ON `fee_structures` (`school_id`);
CREATE INDEX `ix_fee_structures_academic_year_id` ON `fee_structures` (`academic_year_id`);
CREATE INDEX `ix_fee_structures_class_id` ON `fee_structures` (`class_id`);
CREATE INDEX `ix_fee_structures_campus_id` ON `fee_structures` (`campus_id`);
CREATE INDEX `ix_fee_structures_shift_id` ON `fee_structures` (`shift_id`);
CREATE INDEX `ix_fee_structures_program_id` ON `fee_structures` (`program_id`);

CREATE TABLE `fee_structure_items` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `fee_structure_id` TEXT NOT NULL REFERENCES `fee_structures`(`id`) ON DELETE CASCADE,
  `fee_head_id` TEXT NOT NULL REFERENCES `fee_heads`(`id`) ON DELETE RESTRICT,
  `amount` NUMERIC NOT NULL,
  `frequency` TEXT NOT NULL DEFAULT 'monthly',
  `due_day` INTEGER NOT NULL DEFAULT 10,
  `applicable_months` TEXT,
  `late_fine_rule_id` TEXT REFERENCES `late_fine_rules`(`id`) ON DELETE SET NULL,
  PRIMARY KEY (`id`),
  UNIQUE (`fee_structure_id`, `fee_head_id`),
  CHECK (`frequency` IN ('one_time', 'monthly', 'quarterly', 'half_yearly', 'yearly', 'per_term'))
);
CREATE INDEX `ix_fee_structure_items_school_id` ON `fee_structure_items` (`school_id`);
CREATE INDEX `ix_fee_structure_items_fee_structure_id` ON `fee_structure_items` (`fee_structure_id`);
CREATE INDEX `ix_fee_structure_items_fee_head_id` ON `fee_structure_items` (`fee_head_id`);
CREATE INDEX `ix_fee_structure_items_late_fine_rule_id` ON `fee_structure_items` (`late_fine_rule_id`);

CREATE TABLE `student_fee_overrides` (
  `id` TEXT NOT NULL,
