CREATE INDEX `ix_student_fee_overrides_student_id` ON `student_fee_overrides` (`student_id`);
CREATE INDEX `ix_student_fee_overrides_academic_year_id` ON `student_fee_overrides` (`academic_year_id`);
CREATE INDEX `ix_student_fee_overrides_fee_head_id` ON `student_fee_overrides` (`fee_head_id`);
CREATE INDEX `ix_student_fee_overrides_approved_by` ON `student_fee_overrides` (`approved_by`);

CREATE TABLE `discount_schemes` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `discount_kind` TEXT NOT NULL,
  `value_type` TEXT NOT NULL,
  `value` NUMERIC NOT NULL,
  `applies_to_heads` TEXT,
  `auto_rule` TEXT,
  `requires_approval` INTEGER NOT NULL DEFAULT 1,
  `budget_cap` NUMERIC,
  `status` TEXT NOT NULL DEFAULT 'active',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `name`),
  CHECK (`discount_kind` IN ('sibling', 'merit', 'staff_child', 'need_based', 'early_payment', 'scholarship', 'custom')),
  CHECK (`value_type` IN ('percent', 'flat')),
