-- ============ Governance · committee, meetings, policies ============
CREATE TABLE `committees` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `kind` TEXT NOT NULL,
  `status` TEXT NOT NULL DEFAULT 'active',
