CREATE INDEX `ix_committee_members_committee_id` ON `committee_members` (`committee_id`);
CREATE INDEX `ix_committee_members_user_id` ON `committee_members` (`user_id`);

CREATE TABLE `meetings` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `committee_id` TEXT REFERENCES `committees`(`id`) ON DELETE SET NULL,
