  CHECK (`status` IN ('scheduled', 'held', 'cancelled'))
);
CREATE INDEX `ix_meetings_school_id` ON `meetings` (`school_id`);
CREATE INDEX `ix_meetings_committee_id` ON `meetings` (`committee_id`);
