CREATE TABLE `ai_policies` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `features` TEXT,
  `data_scope` TEXT,
  `monthly_budget` NUMERIC,
  `model` TEXT,
  `is_enabled` INTEGER NOT NULL DEFAULT 0,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`)
);
CREATE INDEX `ix_ai_policies_school_id` ON `ai_policies` (`school_id`);

CREATE TABLE `ai_usage_monthly` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `month` TEXT NOT NULL,
  `tokens_in` INTEGER NOT NULL DEFAULT 0,
  `tokens_out` INTEGER NOT NULL DEFAULT 0,
  `cost` NUMERIC NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `month`)
);
CREATE INDEX `ix_ai_usage_monthly_school_id` ON `ai_usage_monthly` (`school_id`);


-- ============ Marketplace, plugins & developer platform ============
CREATE TABLE `plugins` (
  `id` TEXT NOT NULL,
  `slug` TEXT NOT NULL,
  `name` TEXT NOT NULL,
  `vendor` TEXT,
  `description` TEXT,
  `version` TEXT NOT NULL,
  `hooks` TEXT,
  `settings_schema` TEXT,
  `price_monthly` NUMERIC NOT NULL DEFAULT 0,
  `status` TEXT NOT NULL DEFAULT 'draft',
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`slug`),
  CHECK (`status` IN ('draft', 'published', 'suspended'))
);

CREATE TABLE `plugin_installs` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `plugin_id` TEXT NOT NULL REFERENCES `plugins`(`id`) ON DELETE CASCADE,
  `settings` TEXT,
  `is_enabled` INTEGER NOT NULL DEFAULT 1,
  `installed_by` TEXT REFERENCES `users`(`id`) ON DELETE SET NULL,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`school_id`, `plugin_id`)
);
CREATE INDEX `ix_plugin_installs_school_id` ON `plugin_installs` (`school_id`);
CREATE INDEX `ix_plugin_installs_plugin_id` ON `plugin_installs` (`plugin_id`);
CREATE INDEX `ix_plugin_installs_installed_by` ON `plugin_installs` (`installed_by`);

CREATE TABLE `oauth_clients` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `name` TEXT NOT NULL,
  `client_id` TEXT NOT NULL,
  `client_secret_hash` TEXT NOT NULL,
  `redirect_uris` TEXT,
  `scopes` TEXT,
  `is_confidential` INTEGER NOT NULL DEFAULT 1,
  `revoked_at` TEXT,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`client_id`)
);
CREATE INDEX `ix_oauth_clients_school_id` ON `oauth_clients` (`school_id`);

CREATE TABLE `oauth_tokens` (
  `id` TEXT NOT NULL,
  `school_id` TEXT NOT NULL REFERENCES `schools`(`id`) ON DELETE CASCADE,
  `client_id` TEXT NOT NULL REFERENCES `oauth_clients`(`id`) ON DELETE CASCADE,
  `user_id` TEXT REFERENCES `users`(`id`) ON DELETE SET NULL,
  `token_hash` TEXT NOT NULL,
  `kind` TEXT NOT NULL,
  `scopes` TEXT,
  `expires_at` TEXT NOT NULL,
  `revoked_at` TEXT,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`token_hash`),
  CHECK (`kind` IN ('access', 'refresh', 'authorization_code'))
);
CREATE INDEX `ix_oauth_tokens_school_id` ON `oauth_tokens` (`school_id`);
CREATE INDEX `ix_oauth_tokens_client_id` ON `oauth_tokens` (`client_id`);
CREATE INDEX `ix_oauth_tokens_user_id` ON `oauth_tokens` (`user_id`);

CREATE TABLE `template_packs` (
  `id` TEXT NOT NULL,
  `slug` TEXT NOT NULL,
  `name` TEXT NOT NULL,
  `kind` TEXT NOT NULL,
  `locale` TEXT,
  `content` TEXT,
  `version` TEXT NOT NULL,
  `created_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  `updated_at` TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),
  PRIMARY KEY (`id`),
  UNIQUE (`slug`),
  CHECK (`kind` IN ('documents', 'notifications', 'accounting', 'grading', 'curriculum', 'forms'))
);

